/** API presentation uses the existing visual system; all prices and checkout come from the server. */
import {ApiTripController,visibleText,createApiAnnouncements} from './api-model.js';
import {createFavoritesStore,FAVORITES_STORAGE_KEY} from './favorites.js';
import {renderPreferenceForm,revealPreferenceErrors} from './preference-form.js';
import {refinementActions,renderTripChanges,favoriteMismatches} from './trip-usability.js';
import {formatAssistantText} from './message-format.js';
import {destinationNames} from './destination-names.generated.js';
import {hotelDetailRows} from './hotel-presentation.js';
import {counted,adultsLabel,nightsLabel,optionsLabel,formatDate,formatRating,refundLabel,transferLabel,priceRows,tripAssumptions,narrativeView,isoDay,isTrainTrip,trainPresentation,demoDepartureDate,demoTravelerBirthDate,earliestSearchDate,preferenceRequest,departurePeriod,flexiblePackageOverview,humanizeTravelText,activityReferenceView} from './trip-presentation.js';

const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const money=value=>Number.isFinite(value)?value.toLocaleString('ru-RU')+' ₽':'неизвестно';
const names={...destinationNames,MOW:'Москва',SVO:'Москва · Шереметьево'};
const place=code=>Object.hasOwn(names,code)?names[code]:code||'Пока не выбрано';
const day=formatDate;
const localTime=value=>typeof value==='string'&&isoDay(value)&&value.length>=16?day(value)+' · '+value.slice(11,16)+' (UTC'+(value.endsWith('Z')?'+0':value.slice(-6))+')':'время не уточнено';
const extras=items=>(items||[]).map(value=>({return_transfer:'трансфер обратно в аэропорт',visa_and_other_required_extras:'визы и прочие обязательные доплаты',arrival_transfer:'трансфер в отель',activities_and_equipment:'занятия, инструкторы и спортивное оборудование'}[value]||'дополнительные услуги')).join(', ');
const sourceLabel=leg=>leg?.demo_source?.kind==='deterministic_mock'?'<span class="api-source mock">ДЕМО-МОК · расписание и цена сгенерированы</span>':leg?.price_source?'<span class="api-source provider">Aviasales · сохранённая котировка</span>':'<span class="api-source mock">Расчётные демо-данные</span>';
const disclaimer='Демо без списаний. Билеты не выписываются, отель и трансферы не бронируются. Наличие мест и цена покупки не подтверждены.';
const imageFor=index=>['hotel-pool','room-warm','room-light'][index%3];
const fictionalHotel=hotel=>typeof hotel?.hotel_id==='string'&&/^demo:hotel\/[A-Z]{3}-(?:0[1-9]|[1-9][0-9])$/.test(hotel.hotel_id)?'<p class="demo-data-note">Вымышленный демо-отель</p>':'';
const partyLabel=state=>{const group={...state.options[0]?.travelers,...state.brief},ages=Array.isArray(group.children_ages)?group.children_ages:[];return [adultsLabel(group.adults),...(ages.length?[`${counted(ages.length,'ребёнок','ребёнка','детей')} (${ages.map(age=>counted(age,'год','года','лет')).join(', ')})`]:[]),...(group.pets>0?[counted(group.pets,'питомец','питомца','питомцев')]:[])].join(' · ');};

export function mountApiApp({root,modal,icon,config,now=()=>new Date()}){
 let connection='connecting',statusText='',modalOpener=null,modalOpenerKey=null,paymentBusy=false,recoveryTimer=null,recoveryDelay=2000,disposed=false;
 let compared=new Set(),comparisonKey='',compareNotice='',modalSearchKey=null,modalNeedsFresh=false,modalKind='';
 let favoriteStorage=null;try{favoriteStorage=globalThis.localStorage;}catch{}
 let favoritesStore=createFavoritesStore({storage:favoriteStorage,now}),favoriteState=favoritesStore.load(),favoriteFocus=null;
 const openDisclosures=new Set(),announce=createApiAnnouncements();
 // This node survives root renders, so token updates do not re-queue the transcript.
 const liveNode=document.createElement?.('div')||null;
 if(liveNode){liveNode.className='api-sr-status';liveNode.setAttribute('role','status');liveNode.setAttribute('aria-live','polite');liveNode.setAttribute('aria-atomic','true');root.insertAdjacentElement?.('afterend',liveNode);}
 const motionBehavior=()=>globalThis.matchMedia?.('(prefers-reduced-motion: reduce)').matches?'instant':'smooth';
 const toast=message=>{const element=document.getElementById?.('toast');if(!element){if(liveNode)liveNode.textContent=visibleText(message);return;}element.textContent=visibleText(message);element.classList.add('show');setTimeout(()=>element.classList.remove('show'),4000);};
 const modalFeedback=message=>{const status=modal.open&&modal.querySelector?.('#api-modal-status');if(status){status.textContent=visibleText(message);status.scrollIntoView?.({block:'nearest',behavior:'instant'});}else toast(message);};
 let tabStorage=null;try{tabStorage=globalThis.sessionStorage;}catch{}
 const controller=new ApiTripController({onChange:()=>{render();scheduleRecovery();},storage:tabStorage});
 const current=()=>controller.state;
 const actionsBlocked=()=>current().busy||!!current().pendingRequest||current().syncNeeded||current().sessionLost;
 const favoriteMissing=()=>favoriteFocus&&!current().busy&&!current().pendingRequest&&!current().syncNeeded&&!current().sessionLost?favoriteMismatches(favoriteFocus.criteria,current().brief):[];
 const selectionBlocked=()=>current().favoriteRestoreUnconfirmed||favoriteMissing().length>0;
 const selected=()=>current().options.find(option=>option.index===current().selected)||current().options[0];
 const searchReady=()=>!current().stale&&!current().sessionLost&&current().stage!=='collecting';
 const searchKey=()=>JSON.stringify([current().sessionId,current().brief,current().optionKind,current().options]);
 const disclosure=key=>openDisclosures.has(key)?' open':'';
 const button=(action,text,index=null,primary=false)=>`<button class="action-button ${primary?'primary':''}" data-api-action="${action}" ${index===null?'':`data-index="${index}"`} ${actionsBlocked()||['choose','confirm','checkout'].includes(action)&&selectionBlocked()?'disabled':''}>${text}</button>`;
 function controlKey(element){
  if(!element||!root.contains?.(element))return null;
  if(element.classList?.contains('send-button'))return 'composer-send';
  const detail=element.matches?.('summary')&&element.parentElement;
  if(detail?.dataset?.disclosure)return 'disclosure:'+detail.dataset.disclosure;
  if(element.classList?.contains('api-comparison-scroll'))return 'comparison-scroll';
  const data=element.dataset;if(!data?.apiAction&&!data?.apiPrompt)return null;
  const area=['.sidebar','.topbar','.rail','.api-results','.direction-grid','.api-recovery'].find(selector=>element.closest?.(selector))||'';
  return JSON.stringify([area,data.apiAction||'',data.apiPrompt||'',data.index||'',data.orderIndex||'',data.messageIndex||'',data.refineKey||'',data.favoriteId||'']);
 }
 function restoreControl(key){
  if(!key)return;
  const elements=root.querySelectorAll?.('[data-api-action],[data-api-prompt],summary,.api-comparison-scroll,.send-button')||[];
  const replacement=Array.from(elements).find(element=>controlKey(element)===key&&!element.disabled);
  (replacement||root.querySelector('#api-chat-input'))?.focus?.({preventScroll:true});
 }
 function restoreModalOpener(){const opener=modalOpener,key=modalOpenerKey;modalOpener=null;modalOpenerKey=null;if(!opener&&!key)return;if(opener?.isConnected&&opener!==document.body)opener.focus({preventScroll:true});else if(key)restoreControl(key);else root.querySelector('#api-chat-input')?.focus?.({preventScroll:true});}
 function onModalClose(){if(modal.open)return;modalSearchKey=null;modalKind='';restoreModalOpener();}
 function close(){if(modal.open)modal.close();onModalClose();}
 function open(title,body,footer='',searchModal=false){
  if(!modal.open){modalOpener=document.activeElement;modalOpenerKey=controlKey(modalOpener);}
  modalKind='';
  modalSearchKey=searchModal?searchKey():null;
  modalNeedsFresh=searchModal===true;
  modal.innerHTML=`<div class="modal-head"><h2 id="api-modal-title">${esc(title)}</h2><button class="close-modal" data-api-action="close" aria-label="Закрыть окно">${icon('close')}</button></div><div class="modal-body">${body}<p id="api-modal-status" class="api-payment-status" role="status" aria-live="polite" aria-atomic="true"></p></div>${footer?`<div class="modal-footer">${footer}</div>`:''}`;
  modal.setAttribute('aria-labelledby','api-modal-title');if(!modal.open)modal.showModal();else modal.querySelector?.('.close-modal')?.focus({preventScroll:true});modal.scrollTop=0;
 }
 function welcome(){const date=demoDepartureDate();return `<section class="welcome"><div class="eyebrow">ОДИН ДИАЛОГ — ВЕСЬ ПЛАН</div><div class="hero-top"><div><h1>Куда хочется<br>прямо сейчас?</h1><p class="hero-copy">Соберём перелёты, отель и трансфер. Расскажите о поездке — учтём даты, бюджет и важные детали.</p></div><div class="hero-art" aria-hidden="true"><div class="orb"></div><div class="art-card">${icon('plane')}</div><div class="orbit"></div></div></div><div class="quick-prompts">${[['Анталью','Солнце и море'],['Дубай','Город и пляж'],['Мале','На Мальдивы']].map(([name,label])=>`<button class="prompt" data-api-prompt="${esc(`Из Москвы в ${name} ${day(date)} на неделю вдвоём`)}"><span class="prompt-icon">${icon('sun')}</span><div><b>${label}</b><small>${day(date)} · 7 ночей · двое</small></div></button>`).join('')}</div><p class="welcome-note">Сохранённые котировки отмечены Aviasales. Сгенерированные рейсы явно подписаны «ДЕМО-МОК». Проживание и трансферы — расчётные.</p></section>`;}
 function flight(leg,title){if(!leg)return `<div class="api-flight"><b>${esc(title)}</b><span>Перелёт не оценён</span></div>`;return `<div class="api-flight"><b>${esc(title)} · ${esc(place(leg.from))} → ${esc(place(leg.to))}</b>${sourceLabel(leg)}<small>${esc(localTime(leg.departure_at))} → ${esc(localTime(leg.arrival_at))}</small><span>${money(leg.price_rub)} за группу + ${money(leg.baggage_price_rub)} багаж</span>${leg.price_source?`<small>За место: ${money(leg.price_source.seat_price_rub)} · снимок ${day(leg.price_source.recorded_at)}. Наличие не подтверждено.</small>`:'<small>Это учебное расписание и расчётная цена, не котировка поставщика.</small>'}</div>`;}
 function issues(option){return Array.isArray(option.issues)&&option.issues.length?`<div class="risk-note">${option.issues.map(issue=>`<p>${issue.severity==='critical'?'Требует исправления: ':''}${esc(visibleText(issue.message))}</p>`).join('')}</div>`:'';}
 function unknownExtras(option){return extras(option.unpriced_components)||'прочие обязательные доплаты: состав и стоимость не уточнены';}
 function hotelDetails(hotel,compact=false,key=''){const body=`<section class="api-hotel-details" aria-label="Условия проживания"><h4>Условия проживания</h4><dl>${hotelDetailRows(hotel).map(row=>`<div><dt>${esc(row.label)}</dt><dd>${esc(row.value)}</dd></div>`).join('')}</dl><small>Время местное для отеля. Услуги и правила требуют подтверждения перед бронированием.</small></section>`;return compact?`<details class="api-stay-details" data-disclosure="stay-${key}"${disclosure('stay-'+key)}><summary>Правила проживания</summary>${body}</details>`:body;}
 function parts(option){return `${fictionalHotel(option.hotel)}<div class="plan-inline"><div class="plan-line">${icon('building')}<div><b>${esc(option.hotel.name)}</b><small>${day(option.hotel.check_in)} — ${day(option.hotel.check_out)} · ${nightsLabel(option.hotel.nights)}</small></div><b>${money(option.hotel.price_rub)}</b></div>${hotelDetails(option.hotel)}${activityDetails(option)}${flight(option.outbound,'Туда')}${flight(option.inbound,'Обратно')}<div class="plan-line">${icon('car')}<div><b>${esc(transferLabel(option.transfer))}</b><small>Обратный трансфер не оценён</small></div><b>${money(option.transfer?.price_rub)}</b></div><div class="plan-sum"><span>Известная часть стоимости за всех</span><strong>${money(option.known_total_rub)}</strong></div></div><p class="risk-note">Не оценены: ${esc(unknownExtras(option))}. Полная стоимость поездки не подтверждена.</p>${issues(option)}`;}
 function activityDetails(option){
  const view=activityReferenceView(option.activity_reference);if(!view)return '';
  const key='activity-'+option.index;
  return `<p class="api-activity-caption">В направлении: ${esc(view.labels.join(', '))}.</p><details class="api-card-risks" data-disclosure="${key}"${disclosure(key)}><summary>Активности: сведения и источники</summary><p>Справка относится к направлению, а не к выбранному отелю. Занятия, инструкторы и оборудование не включены в сумму; доступность и условия требуют отдельного подтверждения.</p><ul>${view.sources.map(source=>`<li><a href="${esc(source.url)}" target="_blank" rel="noopener noreferrer">${esc(source.title)}</a>${source.checked_on?' · сохранено '+day(source.checked_on):''}</li>`).join('')}</ul></details>`;
 }
 function priceBreakdown(option){const key=`price-${option.index}`;return `<details class="api-price-breakdown" data-disclosure="${key}"${disclosure(key)}><summary>Из чего складывается сумма</summary><dl>${priceRows(option).map(row=>`<div><dt>${esc(row.label)}</dt><dd>${money(row.value)}</dd></div>`).join('')}<div class="api-price-known"><dt>Известная часть за всю группу</dt><dd>${money(option.known_total_rub)}</dd></div></dl><p>Не оценены: ${esc(unknownExtras(option))}. Показанная сумма не является полной ценой поездки.</p></details>`;}
 function assumptions(){
  const state=current();if(!searchReady()||!state.options.length)return '';
  const rows=tripAssumptions(searchReady()?state:{...state,options:[],assumptions:[]});if(!rows.length)return '';
  const compact=!!departurePeriod(state.brief)&&rows.length===1&&rows[0].field==='nights';
  const content=`<section class="api-assumptions" aria-label="Предположения для расчёта"><h2>${state.assumptionsAccepted?'Предположения проверены':'Проверьте предположения'}</h2><p>${state.assumptionsAccepted?'Вы приняли эти условия для поиска. При новом подборе проверка сбросится.':'Эти условия ещё не были названы вами прямо. Их можно принять для поиска или изменить.'}</p><ul>${rows.map(row=>`<li><div><strong>${esc(row.label)}: ${esc(row.display)}</strong><span class="api-assumption-source">${row.source==='default'?'По умолчанию':'Предложено агентом'}</span></div>${row.explanation?`<small>${esc(visibleText(row.explanation))}</small>`:''}</li>`).join('')}</ul><div class="action-row"><button class="action-button primary" data-api-action="accept-assumptions" ${actionsBlocked()||state.assumptionsAccepted?'disabled':''}>${state.assumptionsAccepted?'Предположения проверены':'Подходит для поиска'}</button>${button('edit-preferences','Изменить условия')}</div><small>Проверка предположений не выбирает вариант и не начинает оформление.</small></section>`;
  return compact?`<details class="api-assumptions-compact" data-disclosure="assumptions"${disclosure('assumptions')}><summary>Для расчёта: ${esc(rows[0].display)} · ${state.assumptionsAccepted?'проверено':'можно изменить'}</summary>${content}</details>`:content;
 }
 function assistantMessage(message,index){
  const state=current(),overview=message.flexibleSearchResult===true&&index===state.messages.length-1&&!state.busy&&!message.interrupted&&!message.error?flexiblePackageOverview(state):null;
  const view=narrativeView(humanizeTravelText(visibleText(message.text)));
  if(overview){const key=`message-${index}`;return `<div class="assistant-text api-message-overview">${formatAssistantText(overview)}</div><details id="api-full-answer-${index}" class="api-message-details" data-disclosure="${key}"${disclosure(key)}><summary>Подробнее — условия и источники</summary><div class="assistant-text">${formatAssistantText(view.text)}</div>${state.notes.length?`<ul>${state.notes.map(note=>`<li>${esc(visibleText(note))}</li>`).join('')}</ul>`:''}</details>`;}
  if(!view.compact||message.interrupted||message.error||(current().busy&&index===current().messages.length-1))return `<div class="assistant-text">${formatAssistantText(view.text)}</div>`;
  const key=`message-${index}`;
  return `<div class="assistant-text api-message-overview">${formatAssistantText(view.preview)}</div>${view.warnings.length?`<div class="api-visible-warnings" aria-label="Оговорки полного ответа">${view.warnings.map(text=>`<div class="assistant-text">${formatAssistantText(text)}</div>`).join('')}<button class="api-full-answer-link" data-api-action="expand-message" data-message-index="${index}" aria-controls="api-full-answer-${index}">Все оговорки и условия по вариантам</button></div>`:''}<details id="api-full-answer-${index}" class="api-message-details" data-disclosure="${key}"${disclosure(key)}><summary>Подробнее — весь ответ</summary><div class="assistant-text">${formatAssistantText(view.text)}</div></details>`;
 }
 function comparison(){
  const options=current().options.filter(option=>compared.has(option.index));if(options.length<2)return '';
  const rows=[['Направление',option=>place(option.destination)],['Вылет',option=>day(option.outbound?.departure_at)],['Проживание',option=>`${day(option.hotel.check_in)} — ${day(option.hotel.check_out)} · ${nightsLabel(option.hotel.nights)}`],['Известная часть за группу',option=>money(option.known_total_rub)],['Рейтинг отеля',option=>formatRating(option.hotel.rating)+' / 10'],['Возврат отеля',option=>refundLabel(option.hotel.refundable)],['Трансфер в отель',option=>transferLabel(option.transfer)+(Number.isFinite(option.transfer?.price_rub)?' · '+money(option.transfer.price_rub):' · цена не оценена')]];
  return `<section class="api-comparison" aria-label="Сравнение вариантов"><div class="api-comparison-title"><h2>Сравнение вариантов</h2><button class="action-button" data-api-action="clear-comparison">Очистить сравнение</button></div><div class="api-comparison-scroll" tabindex="0" role="region" aria-label="Таблица сравнения: можно прокрутить по горизонтали"><table><caption>Только текущие предложения; все суммы за показанные компоненты.</caption><thead><tr><th scope="col">Условие</th>${options.map(option=>`<th scope="col">Вариант ${option.index}<br>${esc(option.hotel.name)}</th>`).join('')}</tr></thead><tbody>${rows.map(([label,value])=>`<tr><th scope="row">${label}</th>${options.map(option=>`<td>${esc(value(option))}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="demo-data-note">Полная стоимость не подтверждена: обратный трансфер, визы и прочие обязательные доплаты не оценены. Сравнение не выбирает поездку.</p></section>`;
 }
 function destinationCard(option){
  const code=typeof option.code==='string'&&option.code.length===3&&/^[A-Z]{3}$/.test(option.code)?option.code:null;
  const supported=option.full_trip_supported===true;
  const prompt=code?(supported?`Хочу в ${code}${code==='LED'?', самолётом':''}`:`Расскажи о направлении ${code}`):null;
  const why=Array.isArray(option.why)?humanizeTravelText(option.why.join(' · ')):'Параметры направления требуют уточнения';
  return `<article class="direction-card"><div class="direction-body"><h3>${esc(option.name)}</h3><p>${esc(why)}</p><p class="demo-data-note">${supported?'В демо доступен подбор перелёта, отеля и трансфера. Наличие услуг не подтверждено.':'Только справка: подбор отеля и трансфера пока недоступен'}</p>${Number.isFinite(option.estimated_total_rub)?`<p>Справочная оценка: ${money(option.estimated_total_rub)}. Полная стоимость не подтверждена.</p>`:'<p class="demo-data-note">Стоимость поездки рассчитаем после выбора.</p>'}${prompt?`<button class="action-button primary" data-api-prompt="${esc(prompt)}" ${actionsBlocked()?'disabled':''}>${supported?'Подобрать поездку':'О направлении'}</button>`:'<p class="risk-note">Не удалось определить код направления. Уточните направление в чате.</p>'}</div></article>`;
 }
 function cards(){
  const state=current();
  if(state.sessionLost)return '';
  if(state.stage==='collecting'&&!state.stale&&!state.sessionLost&&!state.options.length&&state.notes.length)return `<div class="empty-result"><strong>Подтверждённых вариантов пока нет.</strong><p>${esc(visibleText(state.notes.join(' ')))}</p><p>Измените даты или условия в чате, чтобы повторить поиск.</p></div>`;
  if(!searchReady())return state.messages.length&&Object.keys(state.brief).length?`<section class="api-search-update"><strong>${state.busy?'Обновляем подбор':'Уточняем условия поездки'}</strong><p>Предыдущие предложения больше не показываются как актуальные. ${state.busy?'Новые варианты появятся после ответа.':'Ответьте в чате или измените условия, чтобы продолжить поиск.'}</p></section>`:'';
  if(state.optionKind==='packages'){
   if(!state.options.length)return `<div class="empty-result"><strong>Подтверждённых вариантов пока нет.</strong><p>${esc(state.notes.join(' '))}</p><p>Измените даты или условия в чате. Подставлять неподтверждённые цены не будем.</p></div>`;
   return `<section class="api-results"><div class="search-caption"><span>${optionsLabel(state.options.length)} с сервера · ${esc(partyLabel(state))}</span><span>Можно сравнить 2–3 варианта</span></div><div class="hotel-grid">${state.options.map((option,index)=>`<article class="hotel-card ${state.selected===option.index?'selected-card':''}"><div class="hotel-photo"><img src="./assets/${imageFor(index)}.svg" alt="Иллюстрация отдыха, не фотография выбранного отеля">${favoriteToggle(option)}<span class="card-photo-label">Иллюстрация</span></div><div class="card-content"><div class="hotel-topline">Вариант ${option.index} · ${esc(place(option.destination))}</div><h3>${esc(option.hotel.name)}</h3>${fictionalHotel(option.hotel)}<div class="api-hotel-rating">${Number.isInteger(option.hotel.stars)?option.hotel.stars+'★ · ':''}Рейтинг ${formatRating(option.hotel.rating)}${Number.isFinite(option.hotel.rating)?' / 10':''}</div>${departurePeriod(state.brief)?`<div class="hotel-location api-card-departure">Вылет ${day(option.outbound.departure_at)}</div>`:''}<div class="hotel-location">${day(option.hotel.check_in)} — ${day(option.hotel.check_out)} · ${nightsLabel(option.hotel.nights)}</div><p class="api-refund">${refundLabel(option.hotel.refundable)}</p>${hotelDetails(option.hotel,true,option.index)}${activityDetails(option)}<p class="api-hotel-transfer"><b>Трансфер в отель:</b> ${esc(transferLabel(option.transfer))}</p><div class="api-card-sources">Туда: ${sourceLabel(option.outbound)}<br>Обратно: ${sourceLabel(option.inbound)}</div><div class="price-amount">${money(option.known_total_rub)}</div><div class="price-total">Известная часть стоимости за всю группу. Прочие доплаты не оценены.</div>${priceBreakdown(option)}${option.issues?.length?issues(option):''}${Array.isArray(option.risks)&&option.risks.length?`<details class="api-card-risks" data-disclosure="risk-${option.index}"${disclosure('risk-'+option.index)}><summary>Риски и ограничения · ${option.risks.length}</summary><ul>${option.risks.map(risk=>`<li>${esc(visibleText(risk))}</li>`).join('')}</ul></details>`:''}<div class="action-row">${button('plan','Состав поездки',option.index)}<button class="action-button primary" data-api-action="choose" data-index="${option.index}" ${actionsBlocked()||selectionBlocked()||option.can_confirm!==true?'disabled':''}>${state.selected===option.index?'Выбран':'Выбрать'}</button></div>${option.can_confirm!==true?'<p class="risk-note">Оформление недоступно: обязательные условия не подтверждены.</p>':''}<div class="action-row">${button('profile','Почему этот отель?',option.index)}<button class="action-button api-compare-toggle" data-api-action="compare" data-index="${option.index}" aria-pressed="${compared.has(option.index)}" ${actionsBlocked()?'disabled':''}>${compared.has(option.index)?'Убрать из сравнения':'Добавить к сравнению'}</button></div></div></article>`).join('')}</div>${compareNotice?`<p class="api-compare-notice">${esc(compareNotice)}</p>`:''}${comparison()}<div class="api-followups">${button('savings','Есть ли даты дешевле?')} ${state.stage==='awaiting_confirmation'?button('confirm','Подтверждаю состав',null,true):''}${state.cart&&!state.order?button('checkout','Продолжить оформление',null,true):''}</div><p class="demo-data-note">${esc(disclaimer)}</p></section>`;
  }
  if(state.optionKind==='destinations')return `<div class="direction-grid">${state.options.map(destinationCard).join('')}</div>`;
  if(state.optionKind==='trains')return `<section class="api-trains" aria-label="Найденные поезда"><div class="search-caption"><span>${optionsLabel(state.options.length)} с сервера · ${esc(partyLabel(state))}</span><span>Поиск без оформления</span></div><div class="api-train-grid">${state.options.map(option=>{const view=trainPresentation(option);return `<article class="api-train-card"><div class="hotel-topline">${esc(place(option.origin?.iata))} → ${esc(place(option.destination?.iata))}</div><h3>Поезд № ${esc(view.number)}</h3><p class="api-train-class">${esc(view.seatClass)}</p><div class="api-train-stations"><div><span>Отправление</span><b>${esc(view.originStation)}</b><small>${esc(localTime(option.departure_at))}</small></div><div><span>Прибытие</span><b>${esc(view.destinationStation)}</b><small>${esc(localTime(option.arrival_at))}</small></div></div><div class="price-amount">${money(option.price_rub)}</div><p class="price-total">За всю группу в одну сторону · обратный билет не включён</p><span class="api-source mock">${esc(view.priceLabel)}</span><p class="api-card-sources">${esc(view.scheduleLabel)}${view.scheduleDetail?`<br>${esc(view.scheduleDetail)}`:''}</p><p class="api-train-limitation">${esc(view.limitation)}</p></article>`;}).join('')}</div><div class="api-followups">${button('edit-preferences','Изменить пассажиров или дату')}</div>${state.notes.length?`<p class="demo-data-note">${esc(visibleText(state.notes.join(' ')))}</p>`:''}</section>`;
  return '';
 }
 function evidence(){const state=current();if(!searchReady())return '';return `${state.profile?.status==='available'?`<details class="api-evidence"><summary>Почему подходит: факты из синтетических отзывов</summary><p>В группе: ${state.profile.segment_review_count} синтетических отзывов. Это демонстрационные примеры, а не настоящие отзывы гостей.</p>${state.profile.evidence.map(row=>`<blockquote>${row.sentiment==='negative'?'Риск':'Плюс'}: «${esc(row.quote)}»</blockquote>`).join('')}</details>`:''}${state.savings?`<div class="api-evidence"><b>Сравнение дат</b><p>${state.savings.comparison_status==='compared'?`Проверено сопоставимых дат: ${state.savings.checked_dates?.filter(row=>row.status==='quoted').length||0}.`:'Нет полного набора котировок — подтвердить экономию нельзя.'}</p>${state.savings.contains_mock?'<p class="api-source mock">Демо-оценка: часть сравниваемых рейсов — моки.</p>':''}${state.savings.suggestions?.map(saving=>`<p>${day(saving.suggested_departure)}: ${money(saving.suggested_total_rub)} · экономия ${money(saving.saving_rub)} по показанным компонентам.</p>`).join('')||'<p>Вариантов с подтверждённой экономией больше 5% не показано.</p>'}<small>Обратный трансфер, визы и прочие доплаты не оценены. Сравнение не меняет выбранную поездку.</small></div>`:''}`;}
 function sidebar(inDialog=false){
  const state=current(),brief=state.brief,rail=isTrainTrip(state),period=state.selected==null?departurePeriod(brief):null,assumed=tripAssumptions(searchReady()?state:{...state,options:[],assumptions:[]});
  const value=field=>brief[field]??assumed.find(row=>row.field===field)?.value;
  const source=field=>{const kind=state.sources[field]||assumed.find(row=>row.field===field)?.source;return ['default','inferred'].includes(kind)?`<small class="api-side-source">${kind==='default'?'По умолчанию':'Предложено агентом'}</small>`:'';};
  return `${inDialog?'':`<button class="drawer-close" data-api-action="close-filters" aria-label="Закрыть параметры">${icon('close')}</button><div class="sidebar-title"><h2>Ваша поездка</h2><span class="synced">${icon('refresh')}Из чата</span></div>`}<div class="side-field"><div class="field-label">Маршрут</div><p class="side-known-value">${esc(place(brief.origin))} → ${esc(place(brief.destination))}</p></div><div class="side-field"><div class="field-label">${rail?'Дата отправления':period?'Период поиска':'Когда'}</div><p class="side-known-value">${period?esc(period):value('start_date')?day(value('start_date')):'Уточним в чате'}${period?'':source('start_date')}${!rail&&value('nights')?` · ${nightsLabel(value('nights'))}${source('nights')}`:''}</p></div><div class="side-field"><div class="field-label">Кто с нами</div><p class="side-known-value">${adultsLabel(value('adults'))}${source('adults')}${brief.children_ages?.length?` · дети: ${brief.children_ages.map(age=>esc(age)).join(', ')} лет`:''}${brief.pets?` · питомцев: ${esc(brief.pets)}`:''}</p></div>${brief.budget_rub?`<div class="side-field"><div class="field-label">Бюджет за всех</div><p class="side-known-value">${money(brief.budget_rub)}</p></div>`:''}${state.needs.length?`<div class="side-features">${state.needs.map(need=>`<span class="feature-chip on">${esc(need.label)}</span>`).join('')}</div>`:''}<p class="demo-data-note">Измените условия кнопкой ниже или напишите в чат. Все суммы пересчитывает сервер.</p>${Object.keys(brief).length?button('edit-preferences','Изменить условия'):''}${!rail&&searchReady()&&state.stage==='awaiting_confirmation'?`<button class="side-plan" data-api-action="confirm" ${actionsBlocked()?'disabled':''}>Подтвердить состав ${icon('arrow')}</button>`:''}${!rail&&searchReady()&&state.cart&&!state.order?`<button class="side-plan" data-api-action="checkout" ${actionsBlocked()?'disabled':''}>Продолжить оформление</button>`:''}${state.order?'<button class="side-plan" data-api-action="success">Демо-заказ и документы</button>':''}`;
 }
 function recovery(){
  const state=current();if(state.busy)return '';
  const button=(action,label)=>`<button class="action-button ${action==='retry'?'primary':''}" data-api-action="${action}">${label}</button>`;
  if(state.sessionLost)return `<section class="api-recovery"><strong>${state.order?'Демо-заказ сохранён':'Переписка сохранена'}</strong><p>${esc(state.order?'Поисковая сессия завершилась. Демо-заказ и документы доступны; для продолжения разговора начните новый поиск.':state.error||'Сервер больше не может восстановить этот ответ.')}</p><div class="action-row">${state.order?button('success','Открыть документы'):state.orders.length||state.ordersSyncNeeded?button('orders','Сохранённые демо-поездки'):''}${state.ordersSyncNeeded?button('reconnect','Проверить связь'):''}${button('restart-session','Начать новый поиск')}</div></section>`;
  if(state.pendingRequest)return `<section class="api-recovery"><strong>${state.connection==='online'?'Можно продолжить':'Восстанавливаем связь'}</strong><p>${esc(state.error||'Ответ прервался. Сообщения и полученная часть ответа сохранены.')}</p><div class="action-row">${button('retry','Повторить сообщение')}${button('reconnect','Проверить связь')}</div><small>Повтор получит тот же ответ, если сообщение уже обработано.</small></section>`;
  if(state.syncNeeded)return `<section class="api-recovery"><strong>Ответ сохранён</strong><p>Осталось обновить состояние поездки.</p>${button('reconnect','Восстановить связь')}</section>`;
  if(state.connection==='offline'||state.connection==='auth')return `<section class="api-recovery"><strong>${state.connection==='auth'?'Нужно войти в сайт':'Нет связи'}</strong><p>Переписка остаётся в этой вкладке. ${state.connection==='auth'?'Повторите вход с прежним паролем.':'Соединение проверяется автоматически.'}</p>${button('reconnect','Проверить связь')}</section>`;
  return '';
 }
 function scheduleRecovery(){
  const state=current(),needed=!disposed&&document.visibilityState!=='hidden'&&!state.busy&&!state.sessionLost&&(state.connection==='offline'||(state.syncNeeded&&state.connection!=='connecting'));
  if(!needed){clearTimeout(recoveryTimer);recoveryTimer=null;if(state.connection==='online')recoveryDelay=2000;return;}
  if(recoveryTimer)return;
  recoveryTimer=setTimeout(()=>{recoveryTimer=null;recoveryDelay=Math.min(30000,recoveryDelay*2);void controller.reconnect();},recoveryDelay);
 }
 function render(){
  favoriteFocus=current().favoriteIntent;
  const state=current(),input=root.querySelector('#api-chat-input'),area=root.querySelector('.chat-scroll');
  const key=searchKey(),sameSearch=key===comparisonKey;if(!sameSearch||!searchReady()){compared.clear();compareNotice='';comparisonKey=key;}
  if(modal.open&&modalSearchKey!==null&&(modalSearchKey!==key||modalNeedsFresh&&(state.stale||state.sessionLost)))close();
  const active=document.activeElement,focusedControl=controlKey(active);
  const horizontal=sameSearch?['.hotel-grid','.direction-grid','.api-comparison-scroll'].map(selector=>[selector,root.querySelector(selector)?.scrollLeft||0]):[];
  for(const item of root.querySelectorAll?.('details[data-disclosure]')||[]){if(item.open)openDisclosures.add(item.dataset.disclosure);else openDisclosures.delete(item.dataset.disclosure);}
  const draft=state.draft,focus=active===input,selection=input?[input.selectionStart,input.selectionEnd]:null;
  const top=area?.scrollTop||0,nearBottom=!area||area.scrollHeight-area.scrollTop-area.clientHeight<160,drawer=root.querySelector('.sidebar')?.classList.contains('open');
  connection=state.connection;
  const hasCriteria=Object.keys(state.brief).length>0;
  root.innerHTML=`<div class="app-shell api-mode ${hasCriteria?'has-criteria':'no-criteria'}"><header class="topbar"><button class="brand" data-api-action="new" aria-label="Новая поездка"><span class="brand-mark">${icon('arch')}</span>островок</button><div class="header-actions"><button class="text-icon api-favorites-nav" data-api-action="favorites" aria-label="Избранное: ${favoriteState.items.length}">${icon('heart')}<span>Избранное${favoriteState.items.length?' · '+favoriteState.items.length:''}</span></button><button class="text-icon" data-api-action="orders" aria-label="Мои поездки">${icon('bag')}<span>Мои поездки</span></button>${hasCriteria?`<button class="mobile-filters" data-api-action="filters">${icon('sliders')}Поездка</button>`:''}</div></header><nav class="rail" aria-label="Основная навигация"><button class="new-trip" data-api-action="new" aria-label="Новая поездка">${icon('plus')}</button><button class="active" data-api-action="home" aria-label="Чат">${icon('chat')}</button><button data-api-action="orders" aria-label="Мои поездки">${icon('bag')}</button><button class="rail-bottom" data-api-action="about" aria-label="Как работает демо">${icon('help')}</button></nav><main class="workspace"><div class="chat-scroll" aria-busy="${state.busy}"><div class="chat-stream">${state.messages.length?state.messages.map((message,index)=>`<div class="message ${message.role} ${message.error?'error':''}">${message.role==='user'?`<div class="user-bubble">${esc(message.text)}</div>`:`<div class="assistant-label"><span class="assistant-mini">${icon('arch')}</span>О!дин запрос</div>${assistantMessage(message,index)}${message.interrupted?'<small class="api-partial-label">Ответ получен не полностью</small>':''}`}</div>`).join(''):welcome()}${state.busy?`<div class="typing-pill">${icon('refresh')}${esc(state.statusText||'Готовим ответ')}</div>`:''}${state.question?.quick_replies?.length?`<div class="action-row">${state.question.quick_replies.map(reply=>`<button class="action-button" data-api-prompt="${esc(reply)}" ${actionsBlocked()?'disabled':''}>${esc(reply)}</button>`).join('')}</div>`:''}${recovery()}${favoriteResult()}${renderTripChanges(state)}${assumptions()}${departurePeriod(state.brief)?'':quickRefinements()}${cards()}${departurePeriod(state.brief)?quickRefinements():''}${evidence()}${state.storageWarning?`<p class="api-error">${esc(state.storageWarning)}</p>`:''}${state.error&&!state.pendingRequest&&!state.syncNeeded&&!state.sessionLost?`<p class="api-error">${esc(state.error)}</p>`:''}</div></div><footer class="composer-wrap"><form id="api-chat-form" class="input-box"><textarea id="api-chat-input" aria-label="Расскажите о поездке" placeholder="Расскажите, куда хочется…" rows="1" maxlength="4000"></textarea><button class="send-button" type="${state.busy?'button':'submit'}" ${state.busy?'data-api-action="stop"':''} aria-label="${state.busy?'Остановить ответ':'Отправить сообщение'}" ${!state.busy&&actionsBlocked()?'disabled':''}>${icon(state.busy?'close':'send')}</button></form><div class="composer-foot"><span>Демо без списаний · Суммы показанных компонентов</span><button data-api-action="about">${icon('shield')}Как это работает</button></div></footer></main><aside class="sidebar ${drawer?'open':''}" aria-label="Параметры поездки">${sidebar()}</aside><button class="drawer-backdrop ${drawer?'open':''}" data-api-action="close-filters" aria-label="Закрыть параметры"></button></div>`;
  const newInput=root.querySelector('#api-chat-input');newInput.value=draft;if(focus){newInput.focus({preventScroll:true});if(selection)newInput.setSelectionRange(...selection);}
  const newArea=root.querySelector('.chat-scroll');newArea.scrollTop=nearBottom?newArea.scrollHeight:top;
  for(const [selector,left] of horizontal){const element=root.querySelector(selector);if(element)element.scrollLeft=left;}
  if(!focus)restoreControl(focusedControl);
  const announcement=announce(state);if(liveNode&&announcement!==null)liveNode.textContent=announcement;
 }
 function plan(index=null){if(!searchReady())return;const option=current().options.find(row=>row.index===index)||selected();if(!option)return;open('Проверьте состав поездки',parts(option),`<span class="demo-data-note">${esc(disclaimer)}</span>${current().stage==='awaiting_confirmation'&&current().selected===option.index?button('confirm','Подтверждаю состав',null,true):button('choose','Выбрать этот вариант',option.index,true)}`,true);}
 async function send(text,{preserveDraft=false,keepFavorite=false}={}){
  if(!text.trim()||current().busy)return;
  if(actionsBlocked()){toast('Сначала восстановите предыдущий ответ.');return;}
  const blocked=selectionBlocked();
  if(blocked&&/^(?:да[,.:]?\s+)?(?:беру|выбираю|выбери|подтверждаю|оформи|оформляй|оплати|оплатить)(?:\s|$)/i.test(text.trim())){toast('Сначала уточните пожелания избранного или примите полученные условия.');return;}
  if(!keepFavorite&&!blocked){favoriteFocus=null;controller.state.favoriteIntent=null;controller.state.favoriteRestoreUnconfirmed=false;}
  const draft=current().draft;close();const input=root.querySelector('#api-chat-input');if(input&&!preserveDraft)input.value='';
  try{const pending=controller.send(text,{searchOnly:blocked||keepFavorite});if(preserveDraft){controller.state.draft=draft;controller.remember();controller.notify();}await pending;afterTurn();}
  catch(error){if(error?.name!=='AbortError')toast(error.message||'Связь прервалась. Можно повторить сообщение.');void controller.reconnect();}
 }
 async function retry(){
  if(current().busy)return;close();
  try{await controller.retry();afterTurn();}
  catch(error){if(error?.name!=='AbortError')toast(error.message||'Пока не удалось получить ответ. Переписка сохранена.');void controller.reconnect();}
 }
 function afterTurn(){if(actionsBlocked())return;if(favoriteFocus){if(!selectionBlocked()){controller.state.favoriteIntent.verified=true;controller.remember();}return;}if(current().stage==='awaiting_confirmation')plan(current().selected);else if(current().cart&&current().stage==='checkout_pending')checkout();}

 function editPreferences(){
  if(actionsBlocked())return;
  open('Изменить условия поиска',renderPreferenceForm(current(),{now:now()}),'','preferences');
 }
 function preferenceErrors(form,errors){
  const message=['adults','start_date','nights','budget_rub','children_ages','pets'].map(field=>errors[field]).find(Boolean);if(message)modalFeedback(message);
  revealPreferenceErrors(form,errors);
 }

 function quickRefinements(){
  const actions=refinementActions(current());if(!actions.length)return '';
  return `<section class="api-refinements" aria-label="Быстрые уточнения"><h2>Уточнить подбор</h2><div class="action-row">${actions.map(action=>`<button class="action-button" data-api-action="refine" data-refine-key="${action.key}" aria-pressed="${action.active}" ${actionsBlocked()?'disabled':''}>${action.active?'✓ ':''}${action.label}</button>`).join('')}</div><p>Остальные условия сохраняются. Повторное нажатие снимает выбранное пожелание.</p></section>`;
 }
 function favoriteToggle(option){
  const saved=favoritesStore.isSaved({brief:current().brief,option});
  return `<button class="heart api-save-favorite ${saved?'on':''}" data-api-action="toggle-favorite" data-index="${option.index}" aria-label="${saved?'Убрать из избранного':'Добавить в избранное'}: ${esc(option.hotel.name)}" aria-pressed="${saved}" ${actionsBlocked()?'disabled':''}>${icon('heart')}</button>`;
 }
 function showFavorites(){
  favoriteState=favoritesStore.load();
  open('Избранное',`<p class="about-text">Отели и пожелания сохраняются на этом устройстве. При возвращении выполним новый поиск: прежняя сумма и наличие того же отеля не гарантируются.</p>${favoriteState.notice?`<p class="api-payment-status">${esc(favoriteState.notice)}</p>`:''}${favoriteState.items.length?`<div class="api-favorites-list">${favoriteState.items.map(item=>`<article class="api-favorite-item"><h3>${esc(item.hotel.name)}</h3>${fictionalHotel(item.hotel)}<p>${esc(place(item.criteria.origin))} → ${esc(place(item.criteria.destination))} · ${day(item.criteria.start_date)} · ${nightsLabel(item.criteria.nights)}</p><p>${adultsLabel(item.criteria.adults)}${item.criteria.children_ages.length?' · дети: '+esc(item.criteria.children_ages.join(', '))+' лет':''}${item.criteria.pets?' · '+counted(item.criteria.pets,'питомец','питомца','питомцев'):''}</p><p class="api-favorite-price">При сохранении: <strong>${money(item.rememberedKnownTotalRub)}</strong> за известные компоненты</p><p class="demo-data-note">Это историческая сумма, не действующее предложение.</p><div class="api-favorite-actions"><button class="primary-button" data-api-action="restore-favorite" data-favorite-id="${esc(item.id)}" ${current().busy||current().pendingRequest||current().syncNeeded?'disabled':''}>Пересчитать</button><button class="secondary-button" data-api-action="remove-favorite" data-favorite-id="${esc(item.id)}" aria-label="Удалить из избранного: ${esc(item.hotel.name)}">Удалить</button></div></article>`).join('')}</div>`:'<p class="modal-empty">Пока ничего не сохранено. Нажмите сердечко на карточке отеля, чтобы вернуться к нему позже.</p>'}`);
  modalKind='favorites';
 }
 function restoreFavorite(id){
  if(current().busy||current().pendingRequest||current().syncNeeded)return;
  const item=favoritesStore.load().items.find(row=>row.id===id);if(!item){showFavorites();modalFeedback('Такого варианта в избранном уже нет.');return;}
  const minimum=earliestSearchDate(now()),date=item.criteria.start_date>=minimum?item.criteria.start_date:'';
  open('Пересчитать избранное',`<h3>${esc(item.hotel.name)}</h3>${fictionalHotel(item.hotel)}<p class="about-text">Начнём новый поиск по сохранённым пожеланиям. Незавершённое оформление будет закрыто; сохранённые демо-заказы останутся в «Моих поездках».</p><p class="demo-data-note">Прежняя сумма относится к предыдущему расчёту. Тот же отель может отсутствовать в новой выдаче; выбор и оформление автоматически не начинаются.</p><form id="api-favorite-form" class="api-preferences-form" data-favorite-id="${esc(id)}"><label for="api-favorite-date">Дата вылета<input id="api-favorite-date" name="start_date" type="date" min="${minimum}" value="${date}" required><small>Если прежняя дата прошла, выберите новую. Не ранее ${day(minimum)}.</small></label><button class="primary-button" type="submit">Начать новый поиск и пересчитать</button></form>`);
  modalKind='favorite-restore';
 }
 function favoriteResult(){
  if(current().sessionLost)return '';
  if(current().favoriteRestoreUnconfirmed&&!favoriteFocus)return `<section class="api-favorite-result"><h2>Проверьте условия поиска</h2><p>Не удалось восстановить пожелания избранного. Выбор пока недоступен. Откройте избранное заново или проверьте текущие параметры.</p><button class="action-button" data-api-action="accept-favorite-results" ${actionsBlocked()?'disabled':''}>Продолжить с полученными условиями</button></section>`;
  if(!favoriteFocus)return '';
  const state=current();
  if(state.busy||state.pendingRequest||state.syncNeeded)return `<section class="api-favorite-result"><h2>Пересчитываем избранное</h2><p>Обновляем варианты по выбранным условиям. Прежнюю сумму нельзя использовать для оформления.</p></section>`;
  const missing=favoriteMissing(),option=state.optionKind==='packages'&&state.options.find(row=>row.hotel?.hotel_id===favoriteFocus.hotel.hotel_id);
  return `<section class="api-favorite-result" aria-label="Новый расчёт избранного"><h2>${esc(favoriteFocus.hotel.name)}: новый подбор</h2>${missing.length?`<p>Текущие условия отличаются от сохранённых. Выбор недоступен: уточните пожелания или явно примите полученные условия.</p><ul>${missing.map(row=>`<li>${esc(row.label)}: ожидалось ${esc(row.expected)}, получено ${esc(row.actual)}</li>`).join('')}</ul><button class="action-button" data-api-action="accept-favorite-results" ${actionsBlocked()?'disabled':''}>Продолжить с полученными условиями</button>`:option?`<p>Сохранённый отель есть в новой выдаче. Сейчас: <strong>${money(option.known_total_rub)}</strong> за известные компоненты всей группы.</p>`:'<p>Сохранённого отеля нет в новой выдаче. Ниже показан результат поиска по выбранным условиям; другой отель не выбран автоматически.</p>'}<p class="demo-data-note">На ${day(favoriteFocus.criteria.start_date)} · ${nightsLabel(favoriteFocus.criteria.nights)}. Прежний расчёт: ${money(favoriteFocus.rememberedKnownTotalRub)}. Текущая цена покупки и наличие услуг не подтверждены.</p></section>`;
 }

 function checkout(){
  const state=current(),cart=state.cart;if(isTrainTrip(state)){toast('Оформление железнодорожных билетов не подключено.');return;}if(!searchReady()){toast('Сначала обновите подбор под текущие условия.');return;}if(actionsBlocked()){toast('Сначала восстановите ответ.');return;}if(!cart?.package){toast('Сначала выберите и подтвердите вариант поездки.');return;}
  const expected=cart.expected_travelers||{adults:state.brief.adults||1,children_ages:state.brief.children_ages||[]};
  const dayString=cart.package.outbound.departure_at.slice(0,10),reference=now();
  const ages=[...Array.from({length:expected.adults},()=>35),...(expected.children_ages||[])];
  const fields=ages.map((age,index)=>{const birth=demoTravelerBirthDate(age,dayString,reference);return `<div class="checkout-grid"><label>Вымышленное имя · путешественник ${index+1}<input name="name-${index}" required minlength="2" maxlength="120" autocomplete="off" value="ДЕМО Путешественник ${index+1}"></label><label>Тестовая дата рождения<input name="birth-${index}" type="date" value="${birth.value}"${birth.min?` min="${birth.min}"`:''}${birth.max?` max="${birth.max}"`:''}${birth.note?` aria-describedby="api-birth-note-${index}"`:''} required>${birth.note?`<small id="api-birth-note-${index}" class="api-payment-status">${esc(birth.note)}</small>`:''}</label></div>`;}).join('');
  open('Демонстрационное оформление',`<div class="demo-note">Используйте вымышленные данные. Банковская карта не нужна. ${esc(disclaimer)}</div>${parts(cart.package)}<form id="api-checkout-form" data-count="${ages.length}"><h3>Тестовые путешественники</h3>${fields}<label class="checkbox-label"><input name="ack-demo" type="checkbox" required><span>Понимаю, что оплата имитируется. Деньги не спишутся, билеты и брони не оформятся.</span></label><label class="checkbox-label"><input name="ack-extras" type="checkbox" required><span>Понимаю, что ${esc(extras(cart.package.unpriced_components))} не оценены и не входят в показанную сумму.</span></label><p id="api-payment-status" class="api-payment-status" role="status">${cart.status==='payment_declined'?'Тестовый отказ. Заказ не создан; можно повторить имитацию оплаты.':''}</p><div class="api-payment-buttons"><button class="secondary-button" type="submit" data-outcome="declined">Проверить отказ оплаты</button><button class="primary-button" type="submit" data-outcome="approved">${icon('lock')}Оплатить в демо</button></div></form>`,'',true);
 }
 function success(entry=null){const order=entry?.order||current().order;if(!order)return;const index=entry?current().orders.indexOf(entry):current().orders.findIndex(row=>row.order.order_id===order.order_id);open('Демо-заказ сохранён',`<div class="success-view"><div class="success-circle">${icon('check')}</div><h3>План поездки готов</h3>${fictionalHotel(order.package.hotel)}<p>${esc(order.package.hotel.name)}<br>${day(order.package.hotel.check_in)} — ${day(order.package.hotel.check_out)}<br><b>${money(order.package.known_total_rub)}</b> по показанным компонентам</p><p>${esc(disclaimer)}</p></div><div class="booking-actions"><button class="primary-button" data-api-action="download-voucher" data-order-index="${index}">${icon('download')}Скачать демо-ваучер</button><button class="secondary-button" data-api-action="download-calendar" data-order-index="${index}">${icon('calendar')}Скачать календарь .ics</button></div><p class="demo-data-note">Обратный трансфер, визы и прочие обязательные доплаты не оценены.</p>`);}
 function orders(){const state=current(),notice=state.ordersSyncNeeded?'<section class="api-recovery" role="status"><strong>Не все сохранённые поездки загружены</strong><p>Ссылки на них сохранены в этой вкладке. Проверьте связь и повторите загрузку.</p><button class="action-button" data-api-action="reload-orders">Повторить загрузку поездок</button></section>':'';open('Мои демо-поездки',notice+(state.orders.length?state.orders.map((entry,index)=>`<article class="plan-inline"><h3>${esc(entry.order.package.hotel.name)}</h3><p>${day(entry.order.package.hotel.check_in)} — ${day(entry.order.package.hotel.check_out)} · ${money(entry.order.package.known_total_rub)}</p><p class="demo-data-note">Оплата имитирована; поставщики услуги не бронировали.</p><button class="action-button primary" data-api-action="order" data-order-index="${index}">Открыть документы</button></article>`).join(''):state.ordersSyncNeeded?'':'<p class="modal-empty">Сохранённых демо-заказов пока нет. Найдите поездку и завершите демонстрационное оформление.</p>'));modalKind='orders';}
 async function download(kind,index){const entry=current().orders[index];modalFeedback(kind==='voucher'?'Готовим демо-ваучер…':'Готовим календарь…');try{const {blob,filename}=await controller.download(kind,entry);const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=filename;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);modalFeedback(kind==='voucher'?'Демо-ваучер скачан.':'Календарь скачан.');}catch(error){modalFeedback(error.message||'Документ пока недоступен.');}}
 function about(){open('Как устроена демонстрация',`<p class="about-text">Тревел-агент помогает подобрать перелёты, отель и трансфер, учесть даты, бюджет и пожелания, а затем собрать план поездки.</p><p class="about-text">Котировки Aviasales сохранены заранее. Сгенерированные рейсы отмечены «ДЕМО-МОК». Стоимость группы, багаж, отель и трансферы расчётные; наличие услуг не подтверждено.</p><p class="demo-note">${esc(disclaimer)}</p><p class="about-text">Изображения — авторские иллюстрации; отзывы — синтетические примеры. Названия и координаты исходных отелей: © участники OpenStreetMap, ODbL. Дополнительные отели помечены как вымышленные демо-отели; их названия и координаты синтетические. Цены и правила услуг расчётные. <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener noreferrer">Источник и условия OpenStreetMap</a>. </p>`);}
 document.addEventListener('click',event=>{
  const target=event.target.closest('[data-api-action],[data-api-prompt]');if(!target||target.disabled)return;
  if(target.dataset.apiPrompt){send(target.dataset.apiPrompt);return;}
  const action=target.dataset.apiAction,index=Number(target.dataset.index);
  if(['choose','confirm','plan','profile','savings','compare'].includes(action)&&(!searchReady()||actionsBlocked()))return;
  if(['choose','confirm','checkout'].includes(action)&&selectionBlocked()){toast('Сначала уточните неперенесённые пожелания избранного.');return;}
  if(action==='accept-favorite-results'){if(actionsBlocked())return;favoriteFocus=null;controller.state.favoriteIntent=null;controller.state.favoriteRestoreUnconfirmed=false;controller.remember();render();toast('Используем текущие условия поиска. Проверьте их перед выбором.');return;}
  if(action==='favorites'){showFavorites();return;}
  if(action==='toggle-favorite'){
   if(actionsBlocked()||!searchReady())return;const option=current().options.find(row=>row.index===index);if(!option?.hotel)return;
   const saved=favoritesStore.isSaved({brief:current().brief,option});
   if(saved){const item=favoritesStore.find({brief:current().brief,option});favoriteState=item?favoritesStore.remove(item.id):favoritesStore.load();}else favoriteState=favoritesStore.add({brief:current().brief,option});
   render();toast(favoriteState.notice);return;
  }
  if(action==='remove-favorite'){favoriteState=favoritesStore.remove(target.dataset.favoriteId);showFavorites();render();modalFeedback(favoriteState.notice||'Удалено из избранного.');return;}
  if(action==='restore-favorite'){restoreFavorite(target.dataset.favoriteId);return;}
  if(action==='refine'){
   if(actionsBlocked())return;const item=refinementActions(current()).find(row=>row.key===target.dataset.refineKey);if(item)send(item.active?item.off:item.on,{preserveDraft:true});return;
  }
  if(action==='retry')retry();else if(action==='reload-orders'){modalFeedback('Загружаем сохранённые поездки…');void controller.reconnect().then(()=>{if(modal.open&&modalKind==='orders')orders();});}else if(action==='reconnect'){recoveryDelay=2000;void controller.reconnect();}else if(action==='restart-session'){controller.restartSession();void controller.reconnect();}else if(action==='close')close();else if(action==='stop')controller.abort?.abort();else if(action==='new'){favoriteFocus=null;close();controller.reset();}else if(action==='home')root.querySelector('.chat-scroll').scrollTo({top:0,behavior:motionBehavior()});
  else if(action==='expand-message'){const index=Number(target.dataset.messageIndex),details=Number.isInteger(index)&&root.querySelector('#api-full-answer-'+index);if(details){details.open=true;openDisclosures.add('message-'+index);details.querySelector('summary')?.focus();}}
  else if(action==='accept-assumptions'){if(!actionsBlocked())controller.acceptAssumptions();}else if(action==='edit-preferences')editPreferences();
  else if(action==='compare'){if(!current().options.some(option=>option.index===index))return;if(compared.has(index)){compared.delete(index);compareNotice='';}else if(compared.size<3){compared.add(index);compareNotice=compared.size<2?'Добавьте ещё один вариант для сравнения.':'';}else compareNotice='Можно сравнить до трёх вариантов. Уберите один, чтобы добавить другой.';render();if(liveNode)liveNode.textContent=compareNotice||'В сравнении вариантов: '+compared.size+'.';}else if(action==='clear-comparison'){compared.clear();compareNotice='';render();if(liveNode)liveNode.textContent='Сравнение очищено.';}
  else if(action==='choose')send(`Беру вариант ${index}`);else if(action==='confirm')send('Подтверждаю');else if(action==='plan')plan(index);else if(action==='checkout')checkout();
  else if(action==='profile')send(`Почему вариант ${index} подходит? Что говорят отзывы?`);else if(action==='savings')send(`Для варианта ${current().selected||current().options[0]?.index||1}: если сдвинуть даты на 1–3 дня, можно сэкономить?`);
  else if(action==='success')success();else if(action==='orders')orders();else if(action==='order')success(current().orders[Number(target.dataset.orderIndex)]);
  else if(action==='download-voucher')download('voucher',Number(target.dataset.orderIndex));else if(action==='download-calendar')download('calendar',Number(target.dataset.orderIndex));
  else if(action==='filters')open('Ваша поездка',sidebar(true),'','parameters');else if(action==='close-filters'){root.querySelector('.sidebar').classList.remove('open');root.querySelector('.drawer-backdrop').classList.remove('open');}
  else if(action==='about')about();else if(action==='prototype'){try{localStorage.setItem('na-maldivy-mode','demo');location.reload();}catch{toast('Не удалось переключить режим.');}}
 });
 document.addEventListener('submit',async event=>{
  if(event.target.id==='api-chat-form'){event.preventDefault();send(root.querySelector('#api-chat-input').value);}
  if(event.target.id==='api-favorite-form'){
   event.preventDefault();const form=event.target;if(current().busy||current().pendingRequest||current().syncNeeded||!form.reportValidity())return;
   const result=favoritesStore.restore(form.dataset.favoriteId,{startDate:String(new FormData(form).get('start_date')||'')});
   if(!result.message){modalFeedback(result.notice);return;}
   controller.restartSession();controller.state.favoriteIntent={...result.favorite,verified:false};controller.state.favoriteRestoreUnconfirmed=false;controller.remember();send(result.message,{preserveDraft:true,keepFavorite:true});return;
  }
  if(event.target.id==='api-preferences-form'){
   event.preventDefault();const form=event.target;if(actionsBlocked())return;
   const data=new FormData(form),rail=form.dataset?.transport==='train',keys=['adults','start_date','children_ages','pets','budget_rub',...(rail?[]:['nights'])];
   const values=Object.fromEntries(keys.map(name=>[name,data.get(name)])),result=preferenceRequest(values,{train:rail,now:now()});
   preferenceErrors(form,result.errors);if(Object.keys(result.errors).length||!form.reportValidity())return;
   send(result.message);return;
  }
  if(event.target.id!=='api-checkout-form')return;
  event.preventDefault();const form=event.target;if(paymentBusy||!form.reportValidity())return;
  const data=new FormData(form),submitter=event.submitter,outcome=submitter?.dataset.outcome||'approved';
  const travelers=Array.from({length:Number(form.dataset.count)},(_,index)=>({full_name:String(data.get('name-'+index)||''),birth_date:String(data.get('birth-'+index)||'')}));
  paymentBusy=true;form.querySelectorAll('button').forEach(button=>button.disabled=true);
  try{const result=await controller.pay({travelers,outcome,acknowledgeDemo:data.get('ack-demo')==='on',acknowledgeUnpriced:data.get('ack-extras')==='on'});if(result?.status==='paid_demo')success();else{const status=form.querySelector('#api-payment-status');if(status)status.textContent='Тестовый отказ. Деньги не списаны, заказ не создан. Можно повторить имитацию оплаты.';}}
  catch(error){const status=form.querySelector('#api-payment-status');if(status)status.textContent=visibleText(error.message||'Оформление не завершено.');}
  finally{paymentBusy=false;if(form.isConnected){form.querySelectorAll('button').forEach(button=>button.disabled=false);const active=document.activeElement;if(modal.open&&modal.contains?.(form)&&submitter?.isConnected&&(!active||active===document.body||active===modal||active===submitter))submitter.focus({preventScroll:true});}}
 });
 document.addEventListener('keydown',event=>{if(event.target.id==='api-chat-input'&&event.key==='Enter'&&!event.shiftKey&&!event.isComposing){event.preventDefault();send(event.target.value);}});
 modal.addEventListener('click',event=>{if(event.target===modal){const rect=modal.getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)close();}});
 modal.addEventListener('close',onModalClose);
 const onInput=event=>{if(event.target.id==='api-chat-input')controller.setDraft(event.target.value);};
 const onOnline=()=>{recoveryDelay=2000;void controller.reconnect();};
 const onOffline=()=>{controller.state.connection='offline';controller.notify();};
 const onVisible=()=>{if(document.visibilityState==='visible'&&(current().connection!=='online'||current().syncNeeded||current().pendingRequest))onOnline();};
 const onHide=()=>controller.remember();
 const onFavoritesStorage=event=>{if(event.storageArea&&event.storageArea!==favoriteStorage)return;if(event.key!==FAVORITES_STORAGE_KEY&&event.key!==null)return;favoritesStore=createFavoritesStore({storage:favoriteStorage,now});favoriteState=favoritesStore.load();render();if(modal.open&&modalKind==='favorites')showFavorites();};
 root.addEventListener('input',onInput);window.addEventListener('online',onOnline);window.addEventListener('offline',onOffline);document.addEventListener('visibilitychange',onVisible);window.addEventListener('pagehide',onHide);window.addEventListener('storage',onFavoritesStorage);
 controller.dispose=()=>{disposed=true;liveNode?.remove?.();clearTimeout(recoveryTimer);root.removeEventListener('input',onInput);window.removeEventListener('online',onOnline);window.removeEventListener('offline',onOffline);document.removeEventListener('visibilitychange',onVisible);window.removeEventListener('pagehide',onHide);window.removeEventListener('storage',onFavoritesStorage);modal.removeEventListener('close',onModalClose);controller.remember();};
 render();void controller.restore().then(()=>controller.reconnect());
 return controller;
}
